const CESYK_LOGO_SRC = "data:image/png;base64,";

function applyCesykLogo() {
  document.querySelectorAll("img[data-cesyk-logo]").forEach((logo) => {
    logo.src = CESYK_LOGO_SRC;
  });
}

if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", applyCesykLogo);
} else {
  applyCesykLogo();
}
